def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # id -> (side, price, arrival_time, index_in_book)
    arrival_time = 0

    def match_order(side, id, price, qty):
        nonlocal arrival_time, trades

        if side == 'buy':
            # Match against sell book (lowest price first, then earliest arrival)
            sell_book.sort(key=lambda x: (x[0], x[1]))

            remaining_qty = qty
            i = 0
            while i < len(sell_book) and remaining_qty > 0:
                sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]

                if sell_price <= price:
                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([id, sell_id, sell_price, trade_qty])

                    remaining_qty -= trade_qty
                    sell_qty -= trade_qty

                    if sell_qty == 0:
                        sell_book.pop(i)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        sell_book[i] = (sell_price, sell_arrival, sell_id, sell_qty)
                        i += 1
                else:
                    break

            return remaining_qty
        else:  # side == 'sell'
            # Match against buy book (highest price first, then earliest arrival)
            buy_book.sort(key=lambda x: (-x[0], x[1]))

            remaining_qty = qty
            i = 0
            while i < len(buy_book) and remaining_qty > 0:
                buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]

                if buy_price >= price:
                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, id, buy_price, trade_qty])

                    remaining_qty -= trade_qty
                    buy_qty -= trade_qty

                    if buy_qty == 0:
                        buy_book.pop(i)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        buy_book[i] = (buy_price, buy_arrival, buy_id, buy_qty)
                        i += 1
                else:
                    break

            return remaining_qty

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            remaining_qty = match_order(side, id, price, qty)

            if remaining_qty > 0:
                if side == 'buy':
                    buy_book.append((price, arrival_time, id, remaining_qty))
                    order_map[id] = ('buy', price, arrival_time, len(buy_book) - 1)
                else:
                    sell_book.append((price, arrival_time, id, remaining_qty))
                    order_map[id] = ('sell', price, arrival_time, len(sell_book) - 1)

            arrival_time += 1

        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            match_order(side, id, price, qty)
            arrival_time += 1

        elif order[0] == 'market':
            _, id, side, qty = order
            match_order(side, id, float('inf') if side == 'buy' else 0, qty)
            arrival_time += 1

        elif order[0] == 'cancel':
            _, id = order
            if id in order_map:
                side, price, arr_time, _ = order_map[id]
                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != id]
                del order_map[id]
            arrival_time += 1

    return trades

